(async () => { const c = window.__clouds; const cv = () => c.report().p11.convergedInfo; const raf = () => new Promise(r => requestAnimationFrame(r));
  const r0 = cv().restarts; c.setSettings({"fitDirect": 0, "fitMs": 0, "fitMsFwd": 0, "fitMsG": 0.5, "fitAmbient": 0, "fitGround": 0, "fitGroundAtten": 0, "fitMsPow": 1, "fitK": 0.4, "fitKUp": 0.3, "fitAmbientForm": 1, "fitMsTauSmooth": 1}); const t = performance.now();
  while (cv().restarts === r0) { await raf(); if (performance.now() - t > 5000) throw new Error('no restart'); }
  while (!cv().done) { await raf(); if (performance.now() - t > 30000) throw new Error('not converged'); }
  for (let i = 0; i < 2; i++) await raf();
  return c.readLinear(); })()

